-- Katalog ve veri parmak izi (salt okunur SELECT). Adım 2-4 ROLLBACK oturumlarının öncesi/sonrası ve Adım 6 tam zincir
-- provasında kullanılır: iki sonuç birebir aynı olmalı. Yalnızca okur; hiçbir şey yazmaz.
select jsonb_build_object(
 'rels', (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
 'fns', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
 'fn_md5', (select md5(string_agg(p.proname||'('||pg_get_function_identity_arguments(p.oid)||')'||p.prosrc||coalesce(p.proconfig::text,'')||p.prosecdef::text||coalesce(p.proacl::text,''), '|' order by p.proname, pg_get_function_identity_arguments(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
 'con_md5', (select md5(string_agg(conrelid::regclass::text||conname||pg_get_constraintdef(oid), '|' order by conrelid::regclass::text, conname)) from pg_constraint where connamespace='public'::regnamespace),
 'trg_md5', (select md5(string_agg(pg_get_triggerdef(t.oid), '|' order by t.tgrelid::regclass::text, t.tgname)) from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not t.tgisinternal),
 'idx_md5', (select md5(string_agg(indexrelid::regclass::text, '|' order by indexrelid::regclass::text)) from pg_index i join pg_class c on c.oid=i.indrelid where c.relnamespace='public'::regnamespace),
 'acl_md5', (select md5(string_agg(relname||coalesce(relacl::text,''), '|' order by relname)) from pg_class where relnamespace='public'::regnamespace),
 'pol_md5', (select md5(string_agg(tablename||policyname||coalesce(qual,'')||coalesce(with_check,''), '|' order by tablename, policyname)) from pg_policies where schemaname='public'),
 'pub_md5', (select md5(coalesce(string_agg(schemaname||'.'||tablename, '|' order by schemaname, tablename),'')) from pg_publication_tables where pubname='supabase_realtime'),
 'view_md5', (select md5(string_agg(c.relname||pg_get_viewdef(c.oid)||coalesce(c.reloptions::text,''), '|' order by c.relname)) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='v'),
 'counters', (select coalesce(jsonb_agg(jsonb_build_array(project_id, register_code, last_value) order by project_id, register_code),'[]') from project_register_counters),
 'seqs', (select jsonb_object_agg(schemaname||'.'||sequencename, last_value) from pg_sequences where schemaname='public'),
 'projects', (select md5(string_agg(id||progress||status, '|' order by id)) from projects),
 'settings', (select md5(string_agg(project_id||prefix, '|' order by project_id)) from project_register_settings),
 'tiz_risks', (select md5(coalesce(string_agg(id::text||status||severity||coalesce(closed_at::text,''), '|' order by id),'')) from project_risks where project_id='test-izmir-ges-2026'),
 'tiz_risk_n', (select count(*) from project_risks where project_id='test-izmir-ges-2026'),
 'tiz_pr_n', (select count(*) from purchase_requests where project_id='test-izmir-ges-2026'),
 'tiz_dr_n', (select count(*) from daily_reports where project_id='test-izmir-ges-2026'),
 'tiz_pd_n', (select count(*) from progress_daily d join project_tasks t on t.id=d.task_id where t.project_id='test-izmir-ges-2026'),
 'tiz_tasks', (select md5(string_agg(id::text||coalesce(activity_id,'')||coalesce(discipline,'')||coalesce(planned_end::text,'')||coalesce(progress_pct::text,'')||coalesce(total_progress::text,'')||coalesce(status::text,'')||task_name, '|' order by id)) from project_tasks where project_id='test-izmir-ges-2026'),
 'all_tasks_n', (select count(*) from project_tasks),
 'aid_n', (select count(*) from project_tasks where activity_id is not null or discipline is not null or wbs_id is not null or area_id is not null),
 'tiz_pi', (select md5(string_agg(id::text||coalesce(planned_qty::text,''), '|' order by id)) from procurement_items where project_id='test-izmir-ges-2026'),
 'notif_n', (select count(*) from notifications),
 'dr_all_n', (select count(*) from daily_reports),
 'cw_n', (select count(*) from project_category_weights),
 'proj_n', (select count(*) from projects),
 'reg_rows', (select (select count(*) from documents)+(select count(*) from rfis)+(select count(*) from drawings)+(select count(*) from project_actions)+(select count(*) from decisions)+(select count(*) from register_status_history)+(select count(*) from project_wbs)+(select count(*) from project_areas)+(select count(*) from area_wbs)),
 'new_objs', (select count(*) from pg_class where relnamespace='public'::regnamespace and relname in ('task_disciplines','activity_id_counters','register_audit','register_permissions')),
 'test_proj', (select count(*) from projects where id like 'zzf1-%' or id like 'ztst-%'),
'ext', (select string_agg(extname, ',' order by extname) from pg_extension),
 'old_tx', (select count(*) from pg_stat_activity where xact_start < now() - interval '5 minutes' and pid <> pg_backend_pid()),
 'stat', (select count(*) from pg_stat_activity where datname = current_database() and pid <> pg_backend_pid() and state is not null and state <> 'idle' and backend_type = 'client backend')
) fp;
